MW.Renderer=class{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.atlas={};this.cam={x:0,y:0};this.time=0;this.floor=null;this.minimap=null;}
 rect(c,x,y,w,h,color){c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),Math.ceil(w),Math.ceil(h));}
 sprite(name,rows,palette,scale=2){const a=document.createElement('canvas');a.width=rows[0].length*scale;a.height=rows.length*scale;const c=a.getContext('2d');rows.forEach((row,y)=>[...row].forEach((p,x)=>{if(p!=='.')this.rect(c,x*scale,y*scale,scale,scale,palette[p]);}));this.atlas[name]=a;return a;}
 hero(color='#739ba8',face=0,frame=0){const k='hero'+color+face+frame;if(this.atlas[k])return this.atlas[k];let rows=['......hhhh......','.....hHHHHh.....','.....hHHHHh.....','....hhHHHHhh....','.....sSSSSs.....','.....sSeESs.....','......sSSs......','.....bbCCbb.....','....bCCCCCCb....','...sCCcCCcCCs...','...sCCcCCcCCs...','....CCcCCcCC....','....CCcCCcCC....','....CCCBBCCC....','....CCCBBCCC....','....ccCCCCcc....','....ccCCCCcc....','.....p.pp.p.....','.....pp..pp.....','.....pp..pp.....','.....DD..DD.....','....DDD..DDD....'];if(face===2){rows=rows.map((r,y)=>y<7?r.replace(/[seES]/g,'H'):r);}if(face===1||face===3)rows=rows.map((r,y)=>y<7?r.slice(0,9)+r.slice(9).replace(/[eE]/g,'S'):r);if(frame)rows[20]='....DDD...DD....';return this.sprite(k,rows,{h:'#17272e',H:'#334454',s:'#b48669',S:'#e6b88b',e:'#252c35',E:'#efcda7',b:'#253e4a',C:color,c:'#486374',B:'#d9c386',p:'#3b454b',D:'#202b33'},3);}
 monster(type,region,boss=false){const k='mob'+type+region+boss;if(this.atlas[k])return this.atlas[k];const palettes=[['#638c58','#a4bd71'],['#496b89','#84acc5'],['#8c7360','#c6ad82'],['#8773a8','#b6a0d0']];const [a,b]=palettes[type%4];const rows=type%3===0?['....aa....aa....','...aBBa..aBBa...','...aBBBBBBBBa...','..aBBBBBBBBBBa..','.aBBbBBBBBBbBBa.','.aBBeeBBBBeeBBa.','.aBBBBBssBBBBBa.','..aBBBBssBBBBa..','...aBBBBBBBBa...','..aBBBaBBaBBBa..','..aBBa....aBBa..','...aa......aa...']:type%3===1?['......aa........','.....aBBa.......','....aBBBBa......','...aBBBBBBa.....','..aBBeeBBeea....','.aBBBBBBBBBBa...','.aBBBsBBsBBBa...','..aBBBssBBBa....','...aBBBBBBa.....','..aBBBBBBBBa....','.aBBaBBBBaBBa...','..aa..aa..aa....']:['.....aaaaaa.....','....aBBBBBBa....','...aBBBBBBBBa...','...aBBeBBeBBa...','....aBssBBBa....','...aCCBBCCBBa...','..aCCCCCCCCCCa..','.aBCCCDDDDCCBBa.','.aBBCCCDDDCCBBa.','..aBCCCDDDCCBa..','...aBBCCBBBa....','...aaa..aaa.....'];return this.sprite(k,rows,{a:'#25333b',B:a,b:b,e:'#ffdd90',s:'#18232c',C:b,D:'#6c6175'},boss?4:2);}
 setWorld(world){this.world=world;const {tile:sz}=MW;const a=document.createElement('canvas');a.width=world.w*sz;a.height=world.h*sz;const c=a.getContext('2d'),pal=world.r.palette;const tiles=[];for(let t=0;t<3;t++)for(let v=0;v<4;v++){const b=document.createElement('canvas');b.width=b.height=sz;const d=b.getContext('2d');this.rect(d,0,0,sz,sz,t===2?pal[5]:t===1?pal[4]:pal[0]);for(let j=0;j<15;j++){const hash=MW.hash(j,v,t),x=hash%46,y=(hash>>>8)%46;this.rect(d,x,y,t===2?12:2,t===2?2:3,t===2?'#91c5c033':t===1?'#6e6d4d45':pal[3]+'55');if(t===0&&hash%3===0)this.rect(d,x+2,y-2,2,3,pal[2]+'55');}if(t===1){this.rect(d,0,0,48,1,pal[3]+'30');}tiles.push(b);}for(let y=0;y<world.h;y++)for(let x=0;x<world.w;x++){const t=world.terrain[y*world.w+x],v=MW.hash(x,y,world.region)%4;c.drawImage(tiles[t*4+v],x*sz,y*sz);if(t===0&&MW.hash(x,y,world.region)%43===0){this.rect(c,x*sz+15,y*sz+19,3,3,world.r.biome==='snow'?'#e8eeeb':'#dec78b');this.rect(c,x*sz+17,y*sz+17,3,3,world.r.biome==='autumn'?'#d59c6c':'#c1bcd0');}}
 // Pixel banks, cobbled plazas and bridges break up the terrain.
 for(const l of MW.landmarks){this.rect(c,(l.x-2)*sz,(l.y-2)*sz,5*sz,5*sz,pal[2]+'50');for(let y=-2;y<3;y++)for(let x=-2;x<3;x++){const q=MW.hash(x,y,l.x);this.rect(c,(l.x+x)*sz+3,(l.y+y)*sz+3,42,42,pal[4]);this.rect(c,(l.x+x)*sz+6,(l.y+y)*sz+6,35,3,pal[3]+'66');this.rect(c,(l.x+x)*sz+3,(l.y+y)*sz+44,42,2,pal[2]+'66');}}
 for(let x=3;x<16;x++){if(x===8||x===9)continue;this.rect(c,x*48,26*48,36,4,'#756851');this.rect(c,x*48,26*48+13,36,4,'#887d5e');this.rect(c,x*48+2,26*48-7,5,31,'#c8b48a');}for(const x of [5,14,19])for(const y of [27,32]){this.rect(c,x*48,y*48-35,4,40,'#645e51');this.rect(c,x*48-4,y*48-40,12,16,'#c58e57');this.rect(c,x*48-2,y*48-36,8,8,'#f0d795');}this.floor=a;}
 tree(o){const c=this.ctx,p=this.world.r.palette,x=o.x,y=o.y;if(o.type==='crystal'){for(let i=0;i<3;i++){this.rect(c,x+i*9-15,y-i*7-32,9,34,['#688baf','#a8c4cf','#747fbb'][i]);this.rect(c,x+i*9-14,y-i*7-32,2,26,'#d5e7dd');}return;}if(o.type==='cactus'){this.rect(c,x-5,y-60,12,70,'#537958');this.rect(c,x-3,y-60,3,67,'#87a56b');this.rect(c,x-22,y-43,8,27,'#537958');this.rect(c,x-17,y-25,19,8,'#537958');this.rect(c,x+6,y-46,19,8,'#537958');this.rect(c,x+19,y-58,7,18,'#537958');return;}if(this.world.r.biome==='bamboo'){for(let i=0;i<3;i++){this.rect(c,x-15+i*13,y-104+(i%2)*12,7,116,'#294e3e');this.rect(c,x-13+i*13,y-104+(i%2)*12,3,111,'#7a9c60');for(let j=0;j<4;j++)this.rect(c,x-16+i*13,y-88+j*23,9,3,'#adbd83');this.rect(c,x-30+i*14,y-80,32,6,p[2]);this.rect(c,x-25+i*14,y-85,26,5,p[0]);}return;}this.shadow(x,y+8,30);this.rect(c,x-8,y-45,16,59,'#4b4038');this.rect(c,x-4,y-43,5,56,'#8d7856');this.rect(c,x+5,y-25,6,22,'#5d5040');const snow=this.world.r.biome==='snow',autumn=this.world.r.biome==='autumn';const colors=snow?['#496571','#819f9a','#bed1ca','#e5e8d8']:autumn?['#684c37','#a86c43','#d39353','#e9b671']:[p[2],p[0],p[1],p[3]];const bands=[[-40,-65,80,23],[-32,-87,65,30],[-24,-105,48,27],[-11,-116,26,17]];bands.forEach(([dx,dy,w,h],i)=>{this.rect(c,x+dx+2,y+dy+4,w,h,colors[0]);this.rect(c,x+dx,y+dy,w-4,h-5,colors[1]);this.rect(c,x+dx+5,y+dy,w-15,7,colors[2]);for(let j=0;j<4;j++)this.rect(c,x+dx+8+j*11,y+dy+7+(j%2)*8,6,4,colors[(j+i)%3+1]);});}
 shadow(x,y,r=18){const c=this.ctx;c.fillStyle='#17242d55';c.beginPath();c.ellipse(x,y,r,r*.28,0,0,7);c.fill();}
 house(b){const c=this.ctx,{x,y,w,h}=b,p=this.world.r.palette;this.rect(c,x+12,y+35,w,h,'#132c2744');this.rect(c,x,y+42,w,h-42,'#d6c19a');this.rect(c,x+7,y+45,w-14,h-52,'#bba682');for(let j=0;j<w;j+=48){this.rect(c,x+j,y+40,8,h-44,'#6c5947');this.rect(c,x+j+8,y+48,3,h-58,'#eee0ad');}this.rect(c,x+w/2-20,y+h-65,40,65,'#3e3e37');this.rect(c,x+w/2-14,y+h-57,28,54,'#665643');for(let j=0;j<4;j++)this.rect(c,x+w/2-13+j*8,y+h-55,2,48,'#8b7757');this.rect(c,x+22,y+75,44,36,'#4e584e');for(let j=0;j<4;j++){this.rect(c,x+25+j*10,y+76,3,32,'#d4bd80');this.rect(c,x+25,y+85+j*7,38,2,'#c5ad7b');}for(let band=0;band<5;band++){const inset=(4-band)*12;this.rect(c,x-20+inset,y-10+band*11,w+40-inset*2,13,p[2]);this.rect(c,x-20+inset,y-10+band*11,w+40-inset*2,3,p[1]);for(let j=0;j<w+40-inset*2;j+=12)this.rect(c,x-20+inset+j,y-7+band*11,3,9,'#a9bcb044');}this.rect(c,x-30,y+42,w+60,8,'#283e3e');this.rect(c,x-28,y+42,w+55,2,'#95a6a0');this.rect(c,x+w-22,y+55,10,30,'#d1a05e');this.rect(c,x+w-21,y+64,8,11,'#ffe2a3');}
 label(text,x,y,color='#ede6cc'){const c=this.ctx;c.font='12px system-ui';c.textAlign='center';const w=c.measureText(text).width;this.rect(c,x-w/2-6,y-14,w+12,21,'#14242bdd');c.fillStyle=color;c.fillText(text,x,y+1);}
 object(o,game){const c=this.ctx,x=o.x,y=o.y,pal=this.world.r.palette;if(o.type==='memory'){if(game.collected.has(o.id))return;this.shadow(x,y,10);this.rect(c,x-3,y-17+Math.sin(this.time*3+o.index)*4,6,8,'#d9e8a4');this.rect(c,x-1,y-21+Math.sin(this.time*3+o.index)*4,2,16,'#fff1b9');}else if(o.type==='chest'){this.shadow(x,y,22);this.rect(c,x-20,y-21,40,25,'#403d36');this.rect(c,x-18,y-25,36,18,game.collected.has(o.id)?'#80795e':'#aa8851');this.rect(c,x-18,y-24,36,3,'#d9bf81');this.rect(c,x-15,y-21,4,23,'#c6ad72');this.rect(c,x+11,y-21,4,23,'#c6ad72');this.rect(c,x-3,y-15,6,9,'#e3d8a4');}else if(o.type==='portal'){this.rect(c,x-26,y-67,12,73,pal[2]);this.rect(c,x+15,y-67,12,73,pal[2]);this.rect(c,x-30,y-70,60,12,pal[4]);for(let i=0;i<5;i++)this.rect(c,x-15+i*7,y-50+Math.sin(this.time*2+i)*15,3,25,'#c4d3e188');this.label(o.next>=12?'여행의 끝':o.name,x,y-90,'#d9d5ad');}else{this.shadow(x,y,34);this.rect(c,x-32,y-5,64,12,pal[2]);this.rect(c,x-26,y-10,52,8,pal[4]);if(o.index===1){this.rect(c,x-10,y-66,20,59,'#5b5653');this.rect(c,x-18,y-72,36,15,'#7b7667');for(let i=0;i<7;i++)this.rect(c,x-16+i*4,y-75-Math.sin(this.time*9+i)*9,5,14,['#ce774f','#eeb56b','#ffe2a3'][i%3]);}else if(o.index===4){this.rect(c,x-19,y-21,38,18,pal[5]);this.rect(c,x-23,y-25,46,5,pal[3]);}else{this.rect(c,x-13,y-59,26,48,'#767e76');this.rect(c,x-11,y-57,5,42,'#bbc1a2');this.rect(c,x-8,y-48,17,3,'#cbb884');this.rect(c,x-7,y-40,14,3,'#cbb884');this.rect(c,x-5,y-33,10,3,'#cbb884');}this.label(o.name,x,y-88);}}
 draw(game,dt){this.time+=dt;const c=this.ctx,p=game.p,w=this.world;this.cam.x=Math.max(0,Math.min(w.w*48-960,p.x-480));this.cam.y=Math.max(0,Math.min(w.h*48-600,p.y-390));c.imageSmoothingEnabled=false;c.clearRect(0,0,960,600);c.save();c.translate(-Math.round(this.cam.x),-Math.round(this.cam.y));c.drawImage(this.floor,0,0);const visible=o=>o.x>this.cam.x-280&&o.x<this.cam.x+1200&&o.y>this.cam.y-180&&o.y<this.cam.y+800;const entities=[];w.homes.forEach(b=>entities.push({y:b.y+b.h,draw:()=>this.house(b)}));w.decor.filter(visible).forEach(o=>entities.push({y:o.y,draw:()=>this.tree(o)}));w.objects.filter(visible).forEach(o=>entities.push({y:o.y,draw:()=>this.object(o,game)}));w.npcs.forEach(n=>entities.push({y:n.y,draw:()=>{this.shadow(n.x,n.y+10);c.drawImage(this.hero(n.color),n.x-24,n.y-66);this.label(n.name,n.x,n.y-83);if(Math.hypot(n.x-p.x,n.y-p.y)<100)this.label('E · '+({guide:'이야기',shop:'상점',smith:'강화',side:'의뢰',tower:'시련'}[n.role]),n.x,n.y+35,'#ebd68f');}}));
 for(const e of game.enemies){if(e.dead||!visible(e))continue;entities.push({y:e.y,draw:()=>{this.shadow(e.x,e.y+10,e.boss?35:18);const spr=this.monster(e.type,w.region,e.boss);c.drawImage(spr,e.x-spr.width/2,e.y-spr.height+12+Math.sin(this.time*4+e.seed)*2);if(e.hp<e.max||e.boss){this.rect(c,e.x-24,e.y-spr.height-2,48,4,'#2f3a43');this.rect(c,e.x-24,e.y-spr.height-2,48*e.hp/e.max,4,e.boss?'#e5a784':'#aecc98');}if(e.boss)this.label(e.name,e.x,e.y-spr.height-18,'#f0d7a0');}});}
 if(game.escort){const e=game.escort;entities.push({y:e.y,draw:()=>{this.shadow(e.x,e.y+10);c.drawImage(this.hero('#b29780'),e.x-24,e.y-66);this.label('순례자 · '+Math.ceil(e.hp)+' HP',e.x,e.y-83);}});}
 entities.push({y:p.y,draw:()=>{if(game.invuln>0&&Math.floor(this.time*16)%2)return;this.shadow(p.x,p.y+10);const frame=game.moving?Math.floor(this.time*9)%2:0;c.drawImage(this.hero('#70a4b6',game.face,frame),p.x-24,p.y-66);this.rect(c,p.x+25,p.y-49,3,50,'#e0e5d4');this.rect(c,p.x+22,p.y-3,10,3,'#d3ad68');}});entities.sort((a,b)=>a.y-b.y).forEach(e=>e.draw());
 for(const t of game.telegraphs){c.fillStyle='#d85c5c33';c.strokeStyle='#f8a07b';c.lineWidth=2;c.beginPath();c.arc(t.x,t.y,t.radius,0,Math.PI*2);c.fill();c.stroke();}if(game.slash>0){c.strokeStyle=game.slashSkill?'#c6edc8':'#ffdda4';c.lineWidth=game.slashSkill?5:3;c.beginPath();c.arc(p.x,p.y-12,game.slashSkill?145:66,-2.2,1.6);c.stroke();}for(const f of game.fx){c.globalAlpha=Math.max(0,f.life);c.fillStyle=f.color;c.font='bold 17px system-ui';c.textAlign='center';c.fillText(f.text,f.x,f.y);}c.globalAlpha=1;
 const target=game.target();if(target&&game.tracking){this.label('◆ 현재 목표',target.x,target.y-115,'#f3dda4');}c.restore();const grad=c.createRadialGradient(480,300,100,480,300,580);grad.addColorStop(0,'#14263600');grad.addColorStop(1,'#10212c44');c.fillStyle=grad;c.fillRect(0,0,960,600);if(['snow','fort','marsh','summit','castle'].includes(w.r.biome)){for(let i=0;i<45;i++){const x=(MW.hash(i,7)%960+this.time*(w.r.biome==='fort'?70:8))%960,y=(MW.hash(i,9)%600+this.time*(w.r.biome==='fort'?300:14))%600;this.rect(c,x,y,w.r.biome==='fort'?1:2,w.r.biome==='fort'?10:2,'#d7e5e744');}}
 this.minimapDraw(game);if(game.tower)this.label(`시련의 탑 ${game.tower.floor} / 30층 · ${game.tower.kills} / ${game.tower.required}`,480,35,'#efd3a0');if(game.event)this.label(`봉화 방어 ${game.event.wave} / 5 · 남은 적 ${game.enemies.filter(e=>e.event&&!e.dead).length}`,480,35,'#efd3a0');
 }
 minimapDraw(game){const c=this.ctx,x=806,y=16,w=138,h=94;this.rect(c,x-4,y-4,w+8,h+8,'#12242ce8');this.rect(c,x,y,w,h,'#334e45');this.rect(c,x,y+28/MW.height*h,w,2,'#adad87');for(const o of this.world.objects){if(o.type==='landmark')this.rect(c,x+o.x/(80*48)*w,y+o.y/(54*48)*h,3,3,'#bdcbbb');}const t=game.target();if(t&&game.tracking)this.rect(c,x+t.x/(80*48)*w,y+t.y/(54*48)*h,4,4,'#e9c27a');this.rect(c,x+game.p.x/(80*48)*w,y+game.p.y/(54*48)*h,4,4,'#d5f2ef');c.font='9px system-ui';c.textAlign='right';c.fillStyle='#c9d5cd';c.fillText('M 世界 지도'.replace('世界','세계'),940,127);}
};
